'use client'

import { useEffect, useState } from 'react'
import { createClient } from '@/lib/supabase/client'
import { sendOrQueue, signedInHere } from '@/lib/offline/use-outbox'
import { WhyOut } from '@/components/why-out'
import { DEFAULT_TZ } from '@/lib/time'

export type CardEvent = {
  id: string
  type: string
  title: string
  starts_at: string
  arrive_at: string | null
  venue: string | null
  address: string | null
  opponent: string | null
  kit_colour: string | null
  round: string | null
  cancelled_at: string | null
}

type Rsvp = { player_id: string; player_name: string; status: string | null; note: string | null }
type Summary = { going: number; maybe: number; out_count: number; no_reply: number }

const CHOICES = [
  { value: 'yes',   label: 'Going', tint: 'var(--yes)' },
  { value: 'maybe', label: 'Maybe', tint: 'var(--maybe)' },
  { value: 'no',    label: 'Out',   tint: 'var(--no)' },
] as const

/**
 * A fixture in the thread, answerable without leaving it.
 *
 * The card reads the event live rather than showing what was true when it was
 * posted, so a game moved on Thursday does not leave the old time sitting in
 * Tuesday's message being read by people arriving an hour early.
 */
export function EventCard({
  event, academyId, isCoach,
}: {
  event: CardEvent
  academyId: string
  isCoach: boolean
}) {
  const [rsvps, setRsvps] = useState<Rsvp[]>([])
  const [summary, setSummary] = useState<Summary | null>(null)
  const [saving, setSaving] = useState<string | null>(null)
  const [asking, setAsking] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)
  const supabase = createClient()

  useEffect(() => {
    let cancelled = false
    supabase.rpc('my_rsvps_for_event', { p_event: event.id }).then(({ data }) => {
      if (!cancelled) setRsvps((data ?? []) as Rsvp[])
    })
    if (isCoach) {
      supabase.rpc('event_rsvp_summary', { p_event: event.id }).then(({ data }) => {
        if (!cancelled) setSummary((data?.[0] ?? null) as Summary | null)
      })
    }
    return () => { cancelled = true }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [event.id, isCoach])

  async function answer(playerId: string, status: string, note?: string) {
    // 0111 requires a reason on 'no'. Asked here rather than let the database
    // refuse it, because "Say why they cannot play" arriving as a red error
    // after the button has already moved reads like a fault.
    if (status === 'no' && !note?.trim()) {
      setAsking(playerId)
      return
    }
    setAsking(null)
    setSaving(playerId)
    setError(null)
    setRsvps((prev) =>
      prev.map((r) => (r.player_id === playerId ? { ...r, status, note: note ?? null } : r))
    )

    // Who is answering, asked of the phone: with no signal the server cannot
    // say, and asking it threw here (X-09).
    const me = await signedInHere()
    if (!me) {
      setSaving(null)
      setError('Not signed in')
      return
    }
    const outcome = await sendOrQueue({
      kind: 'upsert',
      table: 'event_rsvps',
      rows: [
        {
          academy_id: academyId,
          event_id: event.id,
          profile_id: me,
          player_id: playerId,
          status,
          note: note?.trim() || null,
        },
      ],
      onConflict: 'event_id,profile_id,player_id',
    })
    setSaving(null)

    // Only a refusal puts the old answer back. A queued write is saved and
    // has not left the phone yet, and re-reading from the server would
    // replace the parent's answer with the one it has not been told about.
    if (outcome.status === 'refused') {
      setError(outcome.error)
      supabase.rpc('my_rsvps_for_event', { p_event: event.id }).then(({ data }) => {
        setRsvps((data ?? []) as Rsvp[])
      })
    }
  }

  const when = new Date(event.starts_at)
  const cancelled = Boolean(event.cancelled_at)

  return (
    <div className={`w-full overflow-hidden rounded-xl border bg-[var(--surface)] ${cancelled ? 'opacity-60' : ''}`}
         style={{ borderColor: 'var(--brand)' }}>
      <div className="flex items-center gap-2 px-3 py-2" style={{ background: 'var(--brand-faint)' }}>
        <span className="rounded px-1.5 py-0.5 text-[0.625rem] font-bold uppercase tracking-wide text-brand-ink"
              style={{ background: 'var(--brand)' }}>
          {cancelled ? 'Cancelled' : event.type}
        </span>
        {event.round && <span className="text-xs font-medium text-ink-2">{event.round}</span>}
      </div>

      <div className="p-3">
        <p className="font-semibold leading-snug">{event.title}</p>

        <dl className="mt-1.5 grid grid-cols-[auto_1fr] gap-x-3 gap-y-0.5 text-sm">
          <dt className="text-ink-2">When</dt>
          <dd className="tabular-nums">
            {when.toLocaleDateString('en-AU', { timeZone: DEFAULT_TZ, weekday: 'short', day: 'numeric', month: 'short' })}
            {', '}
            {when.toLocaleTimeString('en-AU', { timeZone: DEFAULT_TZ, hour: 'numeric', minute: '2-digit' })}
          </dd>

          {event.arrive_at && (
            <>
              <dt className="text-ink-2">Arrive</dt>
              <dd className="tabular-nums">
                {new Date(event.arrive_at).toLocaleTimeString('en-AU', { timeZone: DEFAULT_TZ, hour: 'numeric', minute: '2-digit' })}
              </dd>
            </>
          )}

          {event.venue && (
            <>
              <dt className="text-ink-2">Where</dt>
              <dd>
                {/* Straight to Maps. A parent reading this is in a car. */}
                <a
                  href={`https://maps.google.com/?q=${encodeURIComponent(event.address ?? event.venue)}`}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="underline underline-offset-2"
                  style={{ color: 'var(--brand-text)' }}
                >
                  {event.venue}
                </a>
              </dd>
            </>
          )}

          {event.kit_colour && (
            <>
              <dt className="text-ink-2">Kit</dt>
              <dd>{event.kit_colour}</dd>
            </>
          )}
        </dl>

        {!cancelled && rsvps.length > 0 && (
          <div className="mt-3 flex flex-col gap-2">
            {rsvps.map((r) => (
              <div key={r.player_id} className="flex flex-col gap-2">
                <div className="flex flex-wrap items-center gap-2">
                  <span className="w-14 flex-none truncate text-sm font-medium text-ink-2">
                    {r.player_name.split(' ')[0]}
                  </span>
                  {/* Drops under the name when larger text no longer fits all three on one line (X-10). */}
                  <div className="flex min-w-fit flex-1 gap-1">
                    {CHOICES.map((c) => {
                      const on = r.status === c.value
                      return (
                        <button
                          key={c.value}
                          onClick={() => answer(r.player_id, c.value)}
                          disabled={saving === r.player_id}
                          className="flex-1 rounded-lg border py-1.5 text-xs font-semibold disabled:opacity-60"
                          style={
                            on
                              ? { borderColor: c.tint, background: `${c.tint}18`, color: c.tint }
                              : { borderColor: 'var(--line)', color: 'var(--ink-2)' }
                          }
                        >
                          {c.label}
                        </button>
                      )
                    })}
                  </div>
                </div>

                {asking === r.player_id && (
                  <WhyOut
                    childName={r.player_name.split(' ')[0]}
                    busy={saving === r.player_id}
                    onSave={(note) => answer(r.player_id, 'no', note)}
                    onCancel={() => setAsking(null)}
                  />
                )}

                {/* The reason they gave, so a parent can see what the coach
                    was told without having to remember it. */}
                {asking !== r.player_id && r.status === 'no' && r.note && (
                  <p className="pl-16 text-xs text-ink-3">{r.note}</p>
                )}
              </div>
            ))}
          </div>
        )}

        {error && (
          <p className="mt-2 text-xs" style={{ color: 'var(--no)' }}>
            {error}
          </p>
        )}

        {!cancelled && (
          <a
            href={`/api/ics/${event.id}`}
            className="mt-3 block rounded-lg border border-[var(--line)] py-2 text-center text-xs font-semibold"
            style={{ color: 'var(--brand-text)' }}
          >
            Add to calendar
          </a>
        )}

        {isCoach && summary && (
          <p className="mt-3 border-t border-[var(--line-2)] pt-2 text-xs text-ink-2">
            <b style={{ color: 'var(--yes)' }}>{summary.going} in</b> · {summary.maybe} maybe ·{' '}
            {summary.out_count} out · {summary.no_reply} no reply
          </p>
        )}

        {!isCoach && rsvps.length === 0 && !cancelled && (
          <p className="mt-2 text-xs text-ink-2">
            No children of yours in this team yet.
          </p>
        )}
      </div>
    </div>
  )
}
